      "kind": "activity",
      "must_do_id": null,
      "note": "The cathedral sits right in the same area, so we trade far-off terraces for its cool, story-filled halls.",
      "must_do_id": null
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch beside the day's wanderings, with room to sit long and let the crew take it easy.",
      "must_do_id": null
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "An open-air finish in the plaza, free and unhurried, perfect for photos before the light fades.",
